package com.ecopulse.model; import jakarta.persistence.*; import java.time.Instant; @Entity @Table(name="buildings") public class Building { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(name="organization_id",nullable=false) public Long organizationId; @Column(nullable=false) public String name; public String location; @Column(name="building_type") public String buildingType; public int occupancy; @Column(name="operating_hours") public double operatingHours; public Double latitude; public Double longitude; @Column(name="created_at") public Instant createdAt=Instant.now(); }
